from collections import deque

def chess_coloring(n):
    grid = [[0]*n for _ in range(n)]
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
    queue = deque([(0, 0, 0, 0)])
    grid[0][0] = 1
    while queue:
        x, y, rainbow, fluttershy = queue.popleft()
        if x == y == n-1:
            return rainbow + fluttershy
        for dx, dy in directions:
            nx, ny = x+dx, y+dy
            if 0 <= nx < n and 0 <= ny < n and grid[nx][ny] == 0:
                if (dx, dy) == (0, 1) and grid[x][ny] == 0:
                    queue.append((nx, ny, rainbow+1, fluttershy))
                    grid[nx][ny] = 1
                elif (dx, dy) == (1, 0) and grid[nx][y] == 0:
                    queue.append((nx, ny, rainbow, fluttershy+1))
                    grid[nx][ny] = 2
    return -1

