def count_squawks(n, m, s, t):
    graph = [[] for _ in range(n)]
    for _ in range(m):
        x, y = map(int, input().split())
        graph[x].append(y)
        graph[y].append(x)

    queue = deque([(s, 1)])
    infected_users = {s}

