from collections import deque

def bfs(graph, start, end):
    queue = deque([[start]])
    visited = set([start])
    while queue:
        path = queue.popleft()
        node = path[-1]
        if node == end:
            return path
        for next_node in graph[node]:
            if next_node not in visited:
                visited.add(next_node)
                queue.append(path + [next_node])
    return None

def solve(graph, start, end):
    if bfs(graph, start, end):
        return len(bfs(graph, start, end)) - 1, bfs(graph, start, end)
    else:
        return "impossible"

