def find_cycle(graph, start):
    stack = [(start, None)]
    visited = set()
    parent = {}
    while stack:
        node, prev = stack.pop()
        if node in visited:
            cycle = []
            while node != prev:
                cycle.append(node)
                node, prev = parent[node], parent[prev]
            cycle.append(node)
            return cycle
        visited.add(node)
        for neighbor in graph[node]:
            if neighbor != prev:
                parent[neighbor] = node
                stack.append((neighbor, node))
    return None

