def find_teacher_free_bus_ride(N, sections):
    total_students = sum(sections)
    bus_capacity = total_students // 3

    if total_students % 3 != 0:
        return -1

    for i in range(1, N):
        first_bus = sum(sections[:i])
        if first_bus > bus_capacity:
            break

        for j in range(i + 1, N):
            second_bus = sum(sections[i:j])
            if first_bus + second_bus > bus_capacity:
                break

            third_bus = total_students - first_bus - second_bus
            if third_bus == bus_capacity:
                return i, j

    return -1

