from collections import defaultdict, deque

def bfs(start, end, L, adj, n):
    dist = [-1] * (n + 1)
    dist[start] = 0
    queue = deque([start])
    while queue:
        node = queue.popleft()
        if node == end:
            break
        for neighbor, cost in adj[node]:
            if dist[neighbor] == -1 and dist[node] + cost <= L:
                dist[neighbor] = dist[node] + cost
                queue.append(neighbor)
    return dist[end]

def solve(N, M, L, roads, Q, queries):
    adj = defaultdict(list)
    for a, b, c in roads:
        adj[a].append((b, c))
        adj[b].append((a, c))

    results = []
    for s, t in queries:
        if s == t:
            results.append(0)
        elif bfs(s, t, L, adj, N) == -1:
            results.append(-1)
        else:
            path = []
            u = s
            while u != t:
                for v, c in adj[u]:
                    if bfs(s, v, L, adj, N) + c == bfs(s, t, L, adj, N):
                        path.append(v)
                        u = v
                        break
            fuel_stops = 0
            current_fuel = L
            for v in path:
                if current_fuel < bfs(s, v, L, adj, N):
                    fuel_stops += 1
                    current_fuel = L
                current_fuel -= bfs(s, v, L, adj, N)
            results.append(fuel_stops)

    return results

