def is_cycle(graph, n):
    visited = [False] * (n + 1)
    for start in range(1, n + 1):
        if not visited[start]:
            stack = deque([start])
            parent = {start: None}
            while stack:
                node = stack.pop()
                visited[node] = True
                for neighbor in graph[node]:
                    if not visited[neighbor]:
                        stack.append(neighbor)
                        parent[neighbor] = node
                    elif parent[node] != neighbor:
                        return True
    return False

