    return True

def dfs(graph, u, color, coloring):
    if u in coloring:
        return coloring[u] == color
    coloring[u] = color
    for v in graph[u]:
        if not dfs(graph, v, 3 - color, coloring):
            return False
    return True

def solve(n, m, n1, n2, n3, edges):
    if n1 + n2 + n3 != n:
        return "NO"

    graph = [[] for _ in range(n)]
    for u, v in edges:
        graph[u-1].append(v-1)
        graph[v-1].append(u-1)

    if max(n1, n2, n3) > (n + 1) // 2:
        return "NO"

