from collections import deque

def min_time_to_drink(n, m, k, grid, start, end):
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
    x1, y1, x2, y2 = start
    x1 -= 1
    y1 -= 1
    x2 -= 1
    y2 -= 1
    queue = deque([(x1, y1, 0)])
    visited = set([(x1, y1, 0)])

