def count_valid_mappings(n, m, maze, instructions):
    directions = ['D', 'L', 'U', 'R']
    start = None
    exit_pos = None
    valid_mappings = 0

    for i in range(n):
        for j in range(m):
            if maze[i][j] == 'S':
                start = (i, j)
            elif maze[i][j] == 'E':
                exit_pos = (i, j)

    def move(pos, direction):
        x, y = pos
        if direction == 'D' and x < n - 1:
            return (x + 1, y)
        elif direction == 'U' and x > 0:
            return (x - 1, y)
        elif direction == 'L' and y > 0:
            return (x, y - 1)
        elif direction == 'R' and y < m - 1:
            return (x, y + 1)
        return None

    def check_mapping(mapping):
        pos = start
        for instruction in instructions:
            direction = directions[int(instruction)]
            new_pos = move(pos, direction)
            if new_pos is None or maze[new_pos[0]][new_pos[1]] == '#':
                return False
            pos = new_pos
            if new_pos == exit_pos:
                return True
        return False

    for perm in permutations(directions):
        if check_mapping(perm):
            valid_mappings += 1
    return valid_mappings

