def count_valid_pairs(n, edges):
    adj_list = {i: [] for i in range(1, n+1)}
    for u, v, c in edges:
        adj_list[u].append((v, c))
        adj_list[v].append((u, c))

    def dfs(node, parent, valid_pairs):
        count = 0
        is_valid = True
        for neighbor, edge_type in adj_list[node]:
            if neighbor == parent:
                continue
            if edge_type == 1:
                is_valid = False
            count += dfs(neighbor, node, valid_pairs) * (1 if is_valid else 0)
        valid_pairs += count
        return count

    total_pairs = 0
    for node in range(1, n+1):
        total_pairs += dfs(node, 0, 0)

    return total_pairs

