def binary_search(arr, target, find_first=False):
    low, high = 0, len(arr) - 1

    while low <= high:
        mid = (low + high) // 2
        if arr[mid] == target:
            if find_first:
                if mid == 0 or arr[mid - 1] < target:
                    return mid
                else:
                    high = mid - 1
            else:
                if mid == len(arr) - 1 or arr[mid + 1] > target:
                    return mid
                else:
                    low = mid + 1
        elif arr[mid] < target:
            low = mid + 1
        else:
            high = mid - 1

    return -1

