def bapc_rigging(n, wins):
    # Create a graph with n nodes
    graph = [[] for _ in range(n)]
    for i, row in enumerate(wins):
        for j, win in enumerate(row):
            if win != 'X':
                graph[i].append((j, win == '1'))

    # Henk is node 0
    henk_wins = [False] * n
    henk_wins[0] = True
    queue = [(0, [])]

    while queue:
        current, path = queue.pop(0)
        for neighbor, is_henk_win in graph[current]:
            if is_henk_win:
                if henk_wins[neighbor]:
                    return "impossible"
                henk_wins[neighbor] = True
                path.append(neighbor)
                queue.append((neighbor, path))
            else:
                if not henk_wins[neighbor]:
                    path.append(neighbor)
                    queue.append((neighbor, path))

    # Reconstruct the path and print the result
    result = []
    while path:
        result.append(path.pop())
    return ' '.join(map(str, result[1:]))

