def restore_string(k, n, strings):
    counter = Counter()
    for s in strings:
        counter[s] += 1

    # A valid restored string should have the same character frequencies
    for freq in counter.values():
        if freq % k != 0:
            return -1

    # Find the most frequent character in each position
    pos_char = [[(c, i) for i, c in enumerate(s)] for s in strings]
    pos_char = [[max(pc, key=lambda x: pc.count(x)) for pc in zip(*pos_char)]]

    # Initialize the restored string
    restored = [''] * n

    # Fill the restored string based on the most frequent characters
    for i, (c, pos) in enumerate(zip(*pos_char)):
        restored[pos] = c

    # Check for invalid swaps
    for i in range(n):
        for j in range(i+1, n):
            if restored[i] == restored[j]:
                return -1

    return ''.join(restored)

