import sys
from typing import List

class SegmentTree:
    def __init__(self, n: int):
        self.tree = [0] * (4 * n)
        self.lazy_replace = [0] * (4 * n)
        self.lazy_reverse = [0] * (4 * n)
        self.lazy_swap = [False] * (4 * n)
        self.n = n

    def build(self, arr: List[int], node: int, l: int, r: int):
        if l == r:
            self.tree[node] = arr[l]
            return
        mid = (l + r) // 2
        self.build(arr, 2 * node, l, mid)
        self.build(arr, 2 * node + 1, mid + 1, r)
        self.tree[node] = self.tree[2 * node] + self.tree[2 * node + 1]

    def push(self, node: int, l: int, r: int):
        if self.lazy_reverse[node] % 2 == 1:
            self.reverse(node, l, r)
            if l != r:
                self.lazy_reverse[2 * node] += 1
                self.lazy_reverse[2 * node + 1] += 1
        if self.lazy_swap[node]:
            self.swap(node, l, r)
            self.lazy_swap[2 * node] = not self.lazy_swap[2 * node]
            self.lazy_swap[2 * node + 1] = not self.lazy_swap[2 * node + 1]
        if self.lazy_replace[node] != 0:
            self.replace(node, l, r, self.lazy_replace[node])
            self.lazy_replace[node] = 0

    def replace(self, node: int, l: int, r: int, val: int):
        self.tree[node] = val * (r - l + 1)

    def reverse(self, node: int, l: int, r: int):
        self.tree[node] = (r - l + 1) - self.tree[node]

    def swap(self, node: int, l: int, r: int):
        self.tree[node] = r - l + 1 - self.tree[node]

    def query(self, node: int, l: int, r: int, ql: int, qr: int) -> int:
        self.push(node, l, r)
        if ql <= l and r <= qr:
            return self.tree[node]
        if qr < l or r < ql:
            return 0
        mid = (l + r) // 2
        return self.query(2 * node, l, mid, ql, qr) + self.query(2 * node + 1, mid + 1, r, ql, qr)

def main():
