from collections import defaultdict

def solve(n, k, constraints):
    ways = 0
    for perm in permutations(range(1, n + 1)):
        if all(perm[i] <= perm[i + 1] for i in range(n - 1)) and \
           all(perm[i] >= perm[i + 1] for i in range(n - 1, 0, -1)):
            if all(constraint(perm, x, y, s) for x, y, s in constraints):
                ways += 1
    return ways

def constraint(perm, x, y, s):
    if s == '=':
        return perm[x - 1] == perm[y - 1]
    elif s == '<':
        return perm[x - 1] < perm[y - 1]
    elif s == '>':
        return perm[x - 1] > perm[y - 1]
    elif s == '<=':
        return perm[x - 1] <= perm[y - 1]
    elif s == '>=':
        return perm[x - 1] >= perm[y - 1]

