                    if c[i-1] == color:
                        if j >= r[i-1] and prev_color != color:
                            dp[i-1][j][color] = min(dp[i-1][j][color], dp[i][j-r[i-1]][prev_color] + 1)
                    else:
                        dp[i-1][j][color] = min(dp[i-1][j][color], dp[i][j][prev_color])

