def solve(n, a):
    target = a[0]
    operations = []
    for i in range(1, n):
        if a[i] != target:
            operations.append((i, i+1, i+2))
            a[i] ^= a[i+1]
            a[i+1] ^= a[i]
            a[i+2] ^= a[i]
            a[i] ^= a[i+2]
        else:
